FORWARD_DECL(
    Coeffs evaluateBasis(float u, const vec4 cv[NUM_CURVE_CONTROL_VERTS]));

void main()
{
    float u = gl_TessCoord.x;
    float v = .5;

    const vec4 cv[NUM_CURVE_CONTROL_VERTS] = {
        inData[0].Peye,
        inData[1].Peye,
        inData[2].Peye,
        inData[3].Peye,
    };

    Coeffs coeffs = evaluateBasis(u, cv);
    vec4 basis = coeffs.basis;
    vec4 pos =
        basis[0] * cv[0] +
        basis[1] * cv[1] +
        basis[2] * cv[2] +
        basis[3] * cv[3];

    outData.Peye = pos;
    gl_Position = vec4(GetProjectionMatrix() * outData.Peye);

    ApplyClipPlanes(outData.Peye);

    ProcessPrimvarsOut(basis, 0, 1, 2, 3, vec2(u, v)); // interpolate varying primvars
