vec3 evaluateNormal(vec4 basis, float u, CurveData vertexData)
{
    vec3 n0 = vertexData.Neye[0];
    vec3 n1 = vertexData.Neye[1];
    vec3 n2 = vertexData.Neye[2];
    vec3 n3 = vertexData.Neye[3];
    return n0 * basis.x
         + n1 * basis.y
         + n2 * basis.z
         + n3 * basis.w;
}

