// Computes the min and max bounds for the given conical frustum in eye space.
Bbox ComputeConicalFrustumBboxEye(const ConicalFrustum conicalFrustum,
                                  const MAT4 shapeToEye)
{
    const vec3 shapeCenterEye = TransformPoint(shapeToEye, vec3(0.0));
    const mat3 shapeToEyeM3 = Mat4ToMat3(shapeToEye);

    // Z column is the spine direction in eye space.
    // Times half-height gives cap center offset.
    const vec3 halfAxisEye  = 0.5 * conicalFrustum.height * shapeToEyeM3[2];
    const vec3 topCenterEye = shapeCenterEye + halfAxisEye;
    const vec3 botCenterEye = shapeCenterEye - halfAxisEye;

    // Radial extents of the top and bottom discs in eye space.
    const vec3 planarLengths = PlanarRowLengths(shapeToEyeM3);

    const vec3 topSizeEye = abs(conicalFrustum.radiusTop) * planarLengths;
    const vec3 botSizeEye = abs(conicalFrustum.radiusBot) * planarLengths;

    Bbox bboxEye;
    bboxEye.minBound = min(topCenterEye - topSizeEye, botCenterEye - botSizeEye);
    bboxEye.maxBound = max(topCenterEye + topSizeEye, botCenterEye + botSizeEye);

    return bboxEye;
}

