// Dot product of a and b with the Z axis component weighted by k instead of 1.
float ComputeWeightedDot(const vec3 a, const vec3 b, const float k)
{
    vec3 w = vec3(1.0, 1.0, k);
    return dot(a * b, w);
}

// The generalized conic surface satisfies:
//   |P.xy|^2 = radius^2, where
//   radius = slope * P.z + interceptRadius,
//   slope = (radiusTop - radiusBot) / height,
//   interceptRadius = (radiusTop + radiusBot) / 2.
// This subsumes the standard cylinder (slope = 0) and cone (one radius zero).
// rayShape.dir need not be normalized.
vec2 ComputeConicalFrustumLateralRoots(const ConicalFrustum conicalFrustum,
                                       const Ray rayShape)
{
    const float invHeight = abs(conicalFrustum.height) > EPS
                            ? 1.0 / conicalFrustum.height
                            : 0.0;
    const float slope = (conicalFrustum.radiusTop - conicalFrustum.radiusBot) * invHeight;
    const float negSlopeSq = -slope * slope;
    const float interceptRadius = 0.5 * (conicalFrustum.radiusTop + conicalFrustum.radiusBot);
    const float slopeInterceptRadius = slope * interceptRadius;

    const float a = ComputeWeightedDot(rayShape.dir, rayShape.dir, negSlopeSq);

    const float halfB = ComputeWeightedDot(rayShape.origin, rayShape.dir, negSlopeSq)
                            - slopeInterceptRadius * rayShape.dir.z;

    const float c = ComputeWeightedDot(rayShape.origin, rayShape.origin, negSlopeSq)
                        - 2.0 * slopeInterceptRadius * rayShape.origin.z
                        - interceptRadius * interceptRadius;

    return ComputeRoots(a, halfB, c);
}

// Computes the (unnormalized) normal direction for the point on the
// given conical frustum in shape space.
// Pshape is assumed to lie on the lateral surface of the conical frustum.
vec3 ComputeConicalFrustumNormal(const ConicalFrustum conicalFrustum,
                                 const vec3 Pshape)
{
    const float invHeight = abs(conicalFrustum.height) > EPS
                            ? 1.0 / conicalFrustum.height
                            : 0.0;
    const float slope = (conicalFrustum.radiusTop - conicalFrustum.radiusBot) * invHeight;
    const float interceptRadius = 0.5 * (conicalFrustum.radiusTop + conicalFrustum.radiusBot);

    // The surface is
    //  F = |P.xy|^2 = radius^2, where
    //  radius = slope * P.z + interceptRadius
    //  => |P.xy|^2 - (slope * P.z + interceptRadius)^2 = 0.
    // Gradient = 2 * (P.xy, -(slope * P.z + interceptRadius) * slope).
    //  Gradient is the direction of steepest ascent = normal direction.
    return vec3(Pshape.xy, -slope * (slope * Pshape.z + interceptRadius));
}

// Checks if a hit is valid for the clipped conical frustum.
bool IsValidConicalFrustumHit(const float t,
                              const float rayShapeOriginZ,
                              const float rayShapeDirZ,
                              const float height)
{
