const uint CONICAL_FRUSTUM_SEG_LATERAL = 0u;
const uint CONICAL_FRUSTUM_SEG_TOP_CAP = 1u;
const uint CONICAL_FRUSTUM_SEG_BOT_CAP = 2u;

// Checks if a hit intersects a cap of the conical frustum.
bool IsValidCapHit(const float t, const float radius, const Ray rayShape)
{
    // Intersection points projected onto the cap planes
    const vec2 pXY = rayShape.origin.xy + t * rayShape.dir.xy;

    // Disc intersections: |Point - DiscCenter|^2 <= radius^2
    return dot(pXY, pXY) <= radius * radius;
}

// Computes sorted hit points in shape space for a ray intersecting the
// conical frustum, including its top and bottom caps.
// rayShape.dir need not be normalized.
SortedHits ComputeHitsShape(const Shape shape, const Ray rayShape)
{
    SortedHits result = CreateDefaultHits();
    int numInserted = 0;

    // Lateral surface checks.
    const vec2 lateralRoots = ComputeConicalFrustumLateralRoots(shape.conicalFrustum,
                                                                rayShape);

    for (int i = 0; i < 2; i++) {
        ConditionalInsertHit(result,
                             numInserted,
                             lateralRoots[i],
                             CONICAL_FRUSTUM_SEG_LATERAL,
                             IsValidConicalFrustumHit(
                                lateralRoots[i],
                                rayShape.origin.z,
                                rayShape.dir.z,
                                shape.conicalFrustum.height));
    }

    // Cap checks.
    const bool rayNotParallelToCaps = abs(rayShape.dir.z) > EPS;
    const float invRayDirZ = rayNotParallelToCaps
                             ? 1.0 / rayShape.dir.z
                             : 0.0;

    // rayOrigin.z + t * rayDir.z = capZ
    // => t = (capZ - rayOrigin.z) / rayDir.z
    const float tTop = (+0.5 * shape.conicalFrustum.height - rayShape.origin.z)
                        * invRayDirZ;

    ConditionalInsertHit(result,
                         numInserted,
                         tTop,
                         CONICAL_FRUSTUM_SEG_TOP_CAP,
                         rayNotParallelToCaps &&
                            IsValidCapHit(tTop,
                                        shape.conicalFrustum.radiusTop,
                                        rayShape));

    const float tBot = (-0.5 * shape.conicalFrustum.height - rayShape.origin.z)
                        * invRayDirZ;

    ConditionalInsertHit(result,
                         numInserted,
                         tBot,
                         CONICAL_FRUSTUM_SEG_BOT_CAP,
                         rayNotParallelToCaps &&
                            IsValidCapHit(tBot,
                                        shape.conicalFrustum.radiusBot,
                                        rayShape));

    // Sort hits in ascending order by t using
    // Batcher's optimal 5-compare network.
    SortHits(result.hits[0], result.hits[2]);
    SortHits(result.hits[1], result.hits[3]);
    SortHits(result.hits[0], result.hits[1]);
    SortHits(result.hits[2], result.hits[3]);
    SortHits(result.hits[1], result.hits[2]);

    return result;
}

// Computes the (unnormalized) shape space normal at the given point on the
// conical frustum.
vec3 ComputeNormalShape(const Shape shape, const Point pointShape)
{
    if (pointShape.segment == CONICAL_FRUSTUM_SEG_TOP_CAP) {
        // +Z
        return vec3(0.0, 0.0, 1.0);
    }
    if (pointShape.segment == CONICAL_FRUSTUM_SEG_BOT_CAP) {
        // -Z
        return vec3(0.0, 0.0, -1.0);
    }

    return ComputeConicalFrustumNormal(shape.conicalFrustum, pointShape.position);
}

