void
ClampTessLevels(inout vec4 tessOuterLo, inout vec4 tessOuterHi)
{
    // Clamp outer tess levels to a minimum of 2 so that we always
    // sample along each edge and in the middle of transition patches.
    const vec4 minOuterTessLevel = vec4(2.0);

    // Values in the tessOuterHi segments which are zero should remain zero.
    const bvec4 maskOuterHi = notEqual(tessOuterHi, vec4(0.0));

    tessOuterLo = max(minOuterTessLevel, tessOuterLo);
    tessOuterHi = max(minOuterTessLevel * vec4(maskOuterHi), tessOuterHi);
}

