    BUCP[0] = vec4(0); BUCP[1] = vec4(0); BUCP[2] = vec4(0);
    DUCP[0] = vec4(0); DUCP[1] = vec4(0); DUCP[2] = vec4(0);

    evalQuadraticBSpline(y, B[0], B[1], B[2], D[0], D[1], D[2]);

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; j++) {
            vec4 A = d[i*3+j];
            BUCP[i] += A * B[j];
            DUCP[i] += A * D[j];
        }
    }

    evalQuadraticBSpline(x, B[0], B[1], B[2], D[0], D[1], D[2]);

    vec4 result = vec4(0);
    du = vec4(0);
    dv = vec4(0);
    for (int i = 0; i < 3; ++i) {
        result += B[i] * BUCP[i];
        du += D[i] * BUCP[i];
        dv += B[i] * DUCP[i];
    }

    du *= ppack.width;
    dv *= ppack.height;

    return result;
}

